"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["4138"],{52455(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.idempotency.processing_conflict","status":409,"titulo":"Request com a mesma Idempotency-Key ainda em processamento; tentar novamente em alguns segundos"},"descricao":{"codigo":"uniplus.idempotency.processing_conflict","requisitos":[],"oQueAconteceu":["Uma requisi\xe7\xe3o concorrente com a mesma `Idempotency-Key` ainda est\xe1 sendo\\nprocessada \u2014 a opera\xe7\xe3o original come\xe7ou, mas ainda n\xe3o terminou de gravar\\numa resposta para reenviar.","Isso acontece tipicamente quando o cliente reenvia a mesma chamada antes que\\na primeira tentativa termine (retentativa disparada cedo demais, ou duas\\nabas/processos enviando a mesma opera\xe7\xe3o em paralelo). Como a resposta da\\ntentativa original ainda n\xe3o existe, o servidor n\xe3o tem o que devolver em\\nreplay, e recusa a segunda tentativa em vez de process\xe1-la tamb\xe9m \u2014 processar\\nas duas duplicaria o efeito da opera\xe7\xe3o, o problema que a `Idempotency-Key`\\nexiste para evitar."],"comoResolver":["Aguarde alguns segundos e tente novamente com a **mesma** `Idempotency-Key`.\\nQuando a tentativa original terminar, o reenvio encontra a resposta pronta e\\nrecebe o replay dela \u2014 sem repetir o efeito da opera\xe7\xe3o. N\xe3o gere uma nova\\nchave s\xf3 para contornar este erro: isso reabriria a chance de duplicar a\\nopera\xe7\xe3o, exatamente o que a chave existe para impedir."],"ondeAparece":["Opera\xe7\xf5es que exigem `Idempotency-Key`"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Idempot\xeancia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);